css:
:root{--mf-bg:#0b0b0f;--mf-bg-glass:rgba(11, 11, 15, 0.82);--mf-surface:#15151c;--mf-primary:#c9a86a;--mf-secondary:#8e8e9c;--mf-accent:#e9d8b0;--mf-text:#f5f2ea;--mf-muted:#9c9a97;--mf-border:#2c2b2e;--mf-border-strong:#4d4c4c;--mf-tint:#26211c;--mf-glow:rgba(233, 216, 176, 0.2);--mf-on-primary:#000000;--mf-font-heading:"Playfair Display", Georgia, "Times New Roman", serif;--mf-font-body:"Inter", system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;--mf-heading-weight:600;--mf-radius:6px;--mf-radius-ctl:4px;--mf-shadow:0 24px 60px -20px rgba(0, 0, 0, 0.6);--mf-max:1200px;--mf-section-y:5.5rem;--mf-gap:1.5rem;--mf-base:18px;--mf-line:1.65}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:5rem;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--mf-bg);color:var(--mf-text)}
.mf-page{font-family:var(--mf-font-body);font-size:var(--mf-base);line-height:var(--mf-line);color:var(--mf-text);background:var(--mf-bg);-webkit-font-smoothing:antialiased;overflow-x:clip}
/* :where() keeps these resets at zero specificity so any component class overrides them */
:where(.mf-page) :is(h1,h2,h3,h4){margin:0;font-family:var(--mf-font-heading);font-weight:var(--mf-heading-weight);line-height:1.15;letter-spacing:-.015em;color:var(--mf-text)}
:where(.mf-page) :is(p,ul){margin:0}
:where(.mf-page) svg{max-width:100%}
.mf-container{width:100%;max-width:var(--mf-max);margin-inline:auto;padding-inline:clamp(1rem,4vw,2rem)}
.mf-section{padding-block:var(--mf-section-y)}
.mf-head{max-width:42rem;margin:0 auto calc(var(--mf-gap) * 2);text-align:center}
.mf-head h2{font-size:clamp(1.75rem,3.6vw,2.6rem);text-wrap:balance}
.mf-head p{margin-top:.9rem;font-size:1.08rem;color:var(--mf-muted)}
.mf-grid{display:grid;gap:var(--mf-gap)}
.mf-btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;padding:.85rem 1.5rem;border:1px solid transparent;border-radius:var(--mf-radius-ctl);font:600 .975rem/1 var(--mf-font-body);text-decoration:none;cursor:pointer;transition:transform .15s ease,background .15s ease,border-color .15s ease}
.mf-btn:hover{transform:translateY(-1px)}
.mf-btn:focus-visible{outline:2px solid var(--mf-accent);outline-offset:2px}
.mf-btn--primary{background:var(--mf-primary);color:var(--mf-on-primary)}
.mf-btn--ghost{background:transparent;color:var(--mf-text);border-color:var(--mf-border-strong)}
.mf-badge{display:inline-block;padding:.32rem .85rem;border:1px solid var(--mf-border-strong);border-radius:999px;background:var(--mf-tint);color:var(--mf-text);font-size:.8rem;font-weight:600;letter-spacing:.01em}
.mf-cols-1{grid-template-columns:repeat(1,minmax(0,1fr))}
.mf-cols-2{grid-template-columns:repeat(2,minmax(0,1fr))}
.mf-cols-3{grid-template-columns:repeat(3,minmax(0,1fr))}
.mf-cols-4{grid-template-columns:repeat(4,minmax(0,1fr))}
.mf-nav{position:sticky;top:0;z-index:30;background:var(--mf-bg-glass);-webkit-backdrop-filter:saturate(1.4) blur(12px);backdrop-filter:saturate(1.4) blur(12px);border-bottom:1px solid var(--mf-border)}
.mf-nav__inner{position:relative;display:flex;align-items:center;gap:1.25rem;min-height:4.25rem}
.mf-nav__brand{margin-right:auto;font-family:var(--mf-font-heading);font-weight:var(--mf-heading-weight);font-size:1.2rem;letter-spacing:-.01em;color:var(--mf-text);text-decoration:none}
.mf-nav__links{display:flex;align-items:center;gap:1.75rem}
.mf-nav__links a:not(.mf-btn){color:var(--mf-muted);text-decoration:none;font-size:.95rem;font-weight:500;transition:color .15s}
.mf-nav__links a:not(.mf-btn):hover{color:var(--mf-text)}
.mf-nav__links .mf-btn{padding:.6rem 1.1rem;font-size:.9rem}
.mf-nav__toggle{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}
.mf-nav__burger{display:none;position:relative;align-items:center;justify-content:center;width:2.5rem;height:2.5rem;border:1px solid var(--mf-border-strong);border-radius:var(--mf-radius-ctl);cursor:pointer}
.mf-nav__burger span,.mf-nav__burger span::before,.mf-nav__burger span::after{display:block;position:relative;width:1.05rem;height:2px;background:var(--mf-text);border-radius:2px;content:""}
.mf-nav__burger span::before{position:absolute;top:-.35rem;left:0}
.mf-nav__burger span::after{position:absolute;top:.35rem;left:0}
.mf-nav__toggle:focus-visible + .mf-nav__burger{outline:2px solid var(--mf-accent);outline-offset:2px}
.mf-hero{position:relative;overflow:hidden}
.mf-hero::before{content:"";position:absolute;inset:0;background:radial-gradient(60% 55% at 50% 0%,var(--mf-glow),transparent 72%);pointer-events:none}
.mf-hero__inner{position:relative;display:grid;gap:3.5rem;align-items:center}
.mf-hero--centered .mf-hero__inner{text-align:center;justify-items:center}
.mf-hero--centered .mf-hero__visual{display:none}
.mf-hero--centered .mf-hero__title,.mf-hero--centered .mf-hero__subtitle{margin-inline:auto}
.mf-hero--split .mf-hero__inner{grid-template-columns:1.05fr .95fr}
.mf-hero__title{max-width:18ch;text-wrap:balance;letter-spacing:-.025em;line-height:1.04}
.mf-hero--split .mf-hero__title{max-width:none}
.mf-hero__subtitle{margin-top:1.4rem;max-width:38rem;font-size:1.15rem;color:var(--mf-muted);text-wrap:pretty}
.mf-hero__copy .mf-badge{margin-bottom:1.4rem}
.mf-hero__actions{display:flex;flex-wrap:wrap;gap:.75rem;margin-top:2.1rem}
.mf-hero--centered .mf-hero__actions{justify-content:center}
.mf-vis{display:grid;gap:1.1rem;padding:1.1rem 1.25rem 1.5rem;background:var(--mf-surface);border:1px solid var(--mf-border);border-radius:var(--mf-radius);box-shadow:var(--mf-shadow)}
.mf-vis__dots{display:flex;gap:.4rem}
.mf-vis__dots i{width:.6rem;height:.6rem;border-radius:50%;background:var(--mf-border-strong)}
.mf-vis__row{display:flex;align-items:center;gap:.75rem}
.mf-vis__pill{flex:0 0 2.2rem;height:2.2rem;border-radius:var(--mf-radius-ctl);background:var(--mf-primary)}
.mf-vis__line{flex:1;height:.65rem;border-radius:999px;background:var(--mf-border-strong)}
.mf-vis__line--short{flex:0 0 45%}
.mf-vis__chart{display:flex;align-items:flex-end;gap:.55rem;height:9rem;padding-top:.5rem}
.mf-vis__chart span{flex:1;border-radius:6px 6px 2px 2px;background:linear-gradient(var(--mf-primary),var(--mf-secondary))}
.mf-vis__chart span:nth-child(1){height:34%}.mf-vis__chart span:nth-child(2){height:52%}
.mf-vis__chart span:nth-child(3){height:41%}.mf-vis__chart span:nth-child(4){height:68%}
.mf-vis__chart span:nth-child(5){height:58%}.mf-vis__chart span:nth-child(6){height:86%}
.mf-vis__chart span:nth-child(7){height:76%}
.mf-hero--md{padding-block:4.5rem}
.mf-hero--md .mf-hero__title{font-size:clamp(2.0rem,5.0vw,3.0rem)}
.mf-hero--split.mf-hero--md .mf-hero__title{font-size:clamp(1.70rem,3.10vw,2.34rem)}
.mf-hero--lg{padding-block:6.5rem}
.mf-hero--lg .mf-hero__title{font-size:clamp(2.4rem,6.5vw,4.2rem)}
.mf-hero--split.mf-hero--lg .mf-hero__title{font-size:clamp(2.04rem,4.03vw,3.28rem)}
.mf-hero--xl{padding-block:8.5rem}
.mf-hero--xl .mf-hero__title{font-size:clamp(2.8rem,9.0vw,5.8rem)}
.mf-hero--split.mf-hero--xl .mf-hero__title{font-size:clamp(2.38rem,5.58vw,4.52rem)}
.mf-feature{padding:1.25rem 1rem}
.mf-icon{display:inline-flex;align-items:center;justify-content:center;width:2.9rem;height:2.9rem;border-radius:min(var(--mf-radius-ctl),16px);background:var(--mf-tint);color:var(--mf-primary)}
.mf-feature h3{margin:1.1rem 0 .5rem;font-size:1.2rem;letter-spacing:-.01em}
.mf-feature p{color:var(--mf-muted)}
.mf-card{display:flex;flex-direction:column;gap:.55rem;padding:1.5rem;overflow:hidden;background:var(--mf-surface);border:1px solid var(--mf-border);border-radius:var(--mf-radius);box-shadow:var(--mf-shadow);transition:transform .2s ease,border-color .2s ease}
.mf-card:hover{transform:translateY(-3px);border-color:var(--mf-border-strong)}
.mf-card__thumb{height:8.5rem;margin:-1.5rem -1.5rem .65rem;background:linear-gradient(135deg,var(--mf-primary),var(--mf-secondary))}
.mf-card:nth-child(3n+2) .mf-card__thumb{background:linear-gradient(135deg,var(--mf-secondary),var(--mf-accent))}
.mf-card:nth-child(3n) .mf-card__thumb{background:linear-gradient(135deg,var(--mf-accent),var(--mf-primary))}
.mf-card h3{font-size:1.15rem;letter-spacing:-.01em}
.mf-card p{color:var(--mf-muted);font-size:.975rem}
.mf-card__meta{font-size:.75rem;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--mf-muted)}
.mf-card__stat{font-family:var(--mf-font-heading);font-weight:var(--mf-heading-weight);font-size:clamp(2rem,4vw,2.9rem);line-height:1;letter-spacing:-.03em}
.mf-card--stat .mf-card__thumb{display:none}
.mf-card--stat .mf-card__stat{order:1}
.mf-card--stat h3{order:2;font-family:var(--mf-font-body);font-size:.95rem;font-weight:500;color:var(--mf-muted)}
.mf-card--stat .mf-card__meta{order:3;text-transform:none;letter-spacing:0;font-size:.85rem;color:var(--mf-text)}
.mf-card--stat p{order:4}
.mf-band{background:var(--mf-surface);border-block:1px solid var(--mf-border)}
.mf-quote{display:flex;flex-direction:column;justify-content:space-between;gap:1.5rem;margin:0;padding:1.6rem;background:var(--mf-bg);border:1px solid var(--mf-border);border-radius:var(--mf-radius)}
.mf-quote blockquote{margin:0;font-size:1.05rem;line-height:1.6}
.mf-quote blockquote::before{content:"\201C";display:block;height:1.7rem;font:700 3rem/1 var(--mf-font-heading);color:var(--mf-primary)}
.mf-quote figcaption{display:flex;align-items:center;gap:.8rem}
.mf-avatar{display:inline-flex;align-items:center;justify-content:center;flex:0 0 2.6rem;width:2.6rem;height:2.6rem;border-radius:50%;background:var(--mf-primary);color:var(--mf-on-primary);font-weight:700}
.mf-quote__who{display:flex;flex-direction:column;line-height:1.3}
.mf-quote__who strong{font-weight:600}
.mf-quote__who span{color:var(--mf-muted);font-size:.9rem}
.mf-tiers{align-items:stretch}
.mf-tier{position:relative;display:flex;flex-direction:column;gap:.9rem;padding:1.75rem;background:var(--mf-surface);border:1px solid var(--mf-border);border-radius:var(--mf-radius);box-shadow:var(--mf-shadow)}
.mf-tier.is-featured{border-color:var(--mf-primary);box-shadow:0 0 0 1px var(--mf-primary),var(--mf-shadow)}
.mf-tier__flag{position:absolute;top:-.85rem;left:1.5rem;background:var(--mf-primary);color:var(--mf-on-primary);border-color:transparent}
.mf-tier h3{font-size:1.15rem}
.mf-tier__price{display:flex;align-items:baseline;gap:.4rem}
.mf-tier__amount{font-family:var(--mf-font-heading);font-weight:var(--mf-heading-weight);font-size:2.6rem;line-height:1;letter-spacing:-.03em}
.mf-tier__period{color:var(--mf-muted)}
.mf-tier__desc{color:var(--mf-muted);font-size:.95rem}
.mf-tier__features{flex:1;display:grid;gap:.65rem;margin:.4rem 0 0;padding:0;list-style:none}
.mf-tier__features li{display:flex;align-items:flex-start;gap:.6rem;font-size:.95rem}
.mf-tier__features svg{flex:0 0 1.1rem;width:1.1rem;height:1.1rem;margin-top:.2rem;color:var(--mf-primary)}
.mf-tier .mf-btn{margin-top:1rem;background:transparent;color:var(--mf-text);border-color:var(--mf-border-strong)}
.mf-tier.is-featured .mf-btn{background:var(--mf-primary);color:var(--mf-on-primary);border-color:transparent}
.mf-faq{display:grid;gap:.75rem;max-width:46rem;margin-inline:auto}
.mf-faq__item{background:var(--mf-surface);border:1px solid var(--mf-border);border-radius:var(--mf-radius)}
.mf-faq__item summary{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1.1rem 1.35rem;cursor:pointer;font-weight:600;list-style:none}
.mf-faq__item summary::-webkit-details-marker{display:none}
.mf-faq__item summary::after{content:"+";flex:0 0 auto;font-size:1.5rem;line-height:1;color:var(--mf-primary);transition:transform .2s ease}
.mf-faq__item[open] summary::after{transform:rotate(45deg)}
.mf-faq__item summary:focus-visible{outline:2px solid var(--mf-accent);outline-offset:2px;border-radius:var(--mf-radius)}
.mf-faq__item p{padding:0 1.35rem 1.25rem;color:var(--mf-muted)}
.mf-cta__panel{position:relative;overflow:hidden;display:grid;justify-items:center;gap:1rem;padding:clamp(2.5rem,6vw,4.5rem) clamp(1.25rem,5vw,3rem);text-align:center;background:var(--mf-primary);color:var(--mf-on-primary);border-radius:var(--mf-radius)}
.mf-cta__panel::before{content:"";position:absolute;inset:0;background:radial-gradient(70% 90% at 15% 0%,rgba(255,255,255,.22),transparent 60%);pointer-events:none}
.mf-cta__panel>*{position:relative}
.mf-cta__panel h2{max-width:22ch;color:inherit;font-size:clamp(1.8rem,4vw,2.8rem);text-wrap:balance}
.mf-cta__panel p{max-width:34rem;font-size:1.1rem;opacity:.92}
.mf-cta__btn{margin-top:.75rem;background:var(--mf-on-primary);color:var(--mf-primary);border-color:transparent}
.mf-footer{padding-block:4rem 2.5rem;background:var(--mf-surface);border-top:1px solid var(--mf-border)}
.mf-footer__top{display:grid;grid-template-columns:1.3fr 2fr;gap:3rem}
.mf-footer__brand{font-family:var(--mf-font-heading);font-weight:var(--mf-heading-weight);font-size:1.25rem}
.mf-footer__tagline{max-width:22rem;margin-top:.6rem;color:var(--mf-muted)}
.mf-footer__cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(9rem,1fr));gap:2rem}
.mf-footer h4{margin-bottom:.9rem;font-family:var(--mf-font-body);font-size:.78rem;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--mf-muted)}
.mf-footer ul{display:grid;gap:.55rem;margin:0;padding:0;list-style:none}
.mf-footer li a{text-decoration:none;color:var(--mf-text)}
.mf-footer li a:hover{text-decoration:underline}
.mf-footer__legal{margin-top:3rem;padding-top:1.5rem;border-top:1px solid var(--mf-border);font-size:.875rem;color:var(--mf-muted)}
@media (max-width:1023px){
.mf-section{padding-block:calc(var(--mf-section-y) * .85)}
.mf-head{margin-bottom:calc(var(--mf-gap) * 1.6)}
.mf-cols-1{grid-template-columns:repeat(1,minmax(0,1fr))}
.mf-cols-2{grid-template-columns:repeat(2,minmax(0,1fr))}
.mf-cols-3{grid-template-columns:repeat(2,minmax(0,1fr))}
.mf-cols-4{grid-template-columns:repeat(2,minmax(0,1fr))}
.mf-nav__links{gap:1.1rem}
.mf-nav__links a:not(.mf-btn){font-size:.9rem}
.mf-hero--split .mf-hero__inner{grid-template-columns:1fr;text-align:center;justify-items:center}
.mf-hero--split .mf-hero__actions{justify-content:center}
.mf-hero--split .mf-hero__visual{width:min(100%,32rem)}
.mf-hero--split .mf-hero__title{max-width:18ch}
.mf-hero--split.mf-hero--md .mf-hero__title{font-size:clamp(2.0rem,5.0vw,2.55rem)}
.mf-hero--split.mf-hero--lg .mf-hero__title{font-size:clamp(2.4rem,6.5vw,3.57rem)}
.mf-hero--split.mf-hero--xl .mf-hero__title{font-size:clamp(2.8rem,9.0vw,4.93rem)}
.mf-footer__top{grid-template-columns:1fr;gap:2.25rem}
}
@media (max-width:639px){
.mf-section{padding-block:calc(var(--mf-section-y) * .62)}
.mf-head{margin-bottom:1.75rem}
.mf-container{padding-inline:1.1rem}
.mf-cols-1{grid-template-columns:repeat(1,minmax(0,1fr))}
.mf-cols-2{grid-template-columns:repeat(1,minmax(0,1fr))}
.mf-cols-3{grid-template-columns:repeat(1,minmax(0,1fr))}
.mf-cols-4{grid-template-columns:repeat(1,minmax(0,1fr))}
.mf-nav-collapse .mf-nav__burger{display:inline-flex}
.mf-nav-collapse .mf-nav__links{display:none;position:absolute;top:100%;left:0;right:0;flex-direction:column;align-items:stretch;gap:.25rem;padding:.75rem 1rem 1rem;background:var(--mf-surface);border-bottom:1px solid var(--mf-border);box-shadow:var(--mf-shadow)}
.mf-nav-collapse .mf-nav__toggle:checked ~ .mf-nav__links{display:flex}
.mf-nav-collapse .mf-nav__links a:not(.mf-btn){padding:.75rem .5rem;font-size:1rem}
.mf-nav-collapse .mf-nav__links .mf-btn{margin-top:.5rem}
.mf-nav-stack .mf-nav__inner{flex-wrap:wrap;padding-block:.75rem;row-gap:.5rem}
.mf-nav-stack .mf-nav__links{width:100%;flex-wrap:wrap;gap:.25rem 1.1rem}
.mf-hero.mf-hero--md{padding-block:3.0rem}
.mf-hero.mf-hero--lg{padding-block:3.6rem}
.mf-hero.mf-hero--xl{padding-block:4.7rem}
.mf-hero__actions{width:100%}
.mf-hero__actions .mf-btn{flex:1 1 100%}
.mf-hero__subtitle{font-size:1.05rem}
.mf-vis__chart{height:7rem}
.mf-footer{padding-block:3rem 2rem}
.mf-footer__cols{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important;scroll-behavior:auto!important}}

react.content:
import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

export default defineConfig({ plugins: [react()] });

import React from "react";
import { createRoot } from "react-dom/client";
import App from "./App.jsx";
import "./styles.css";

createRoot(document.getElementById("root")).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { design } from "./design.js";
import Navbar from "./components/Navbar.jsx";
import Hero from "./components/Hero.jsx";
import Features from "./components/Features.jsx";
import Cards from "./components/Cards.jsx";
import Testimonials from "./components/Testimonials.jsx";
import Pricing from "./components/Pricing.jsx";
import Faq from "./components/Faq.jsx";
import Cta from "./components/Cta.jsx";
import Footer from "./components/Footer.jsx";

// One entry per component in src/components. To add a section, append an
// object with a matching `type` to `sections` in src/design.js.
const COMPONENTS = {
  navbar: Navbar,
  hero: Hero,
  features: Features,
  cards: Cards,
  testimonials: Testimonials,
  pricing: Pricing,
  faq: Faq,
  cta: Cta,
  footer: Footer,
};

function Section({ section }) {
  const Component = COMPONENTS[section.type];
  return Component ? <Component content={section} /> : null;
}

export default function App() {
  const navbar = design.sections.filter((s) => s.type === "navbar");
  const footer = design.sections.filter((s) => s.type === "footer");
  const main = design.sections.filter((s) => s.type !== "navbar" && s.type !== "footer");

  return (
    <div className={`mf-page mf-nav-${design.responsive.mobile_nav}`}>
      {navbar.map((s) => (
        <Section key={s.id} section={s} />
      ))}
      <main>
        {main.map((s) => (
          <Section key={s.id} section={s} />
        ))}
      </main>
      {footer.map((s) => (
        <Section key={s.id} section={s} />
      ))}
    </div>
  );
}

export const design = {
  "name": "Parity Test",
  "theme": {
    "background": "#0b0b0f",
    "surface": "#15151c",
    "primary": "#c9a86a",
    "secondary": "#8e8e9c",
    "accent": "#e9d8b0",
    "text": "#f5f2ea"
  },
  "typography": {
    "heading": "Playfair Display",
    "body": "Inter",
    "scale": "large"
  },
  "layout": {
    "max_width": "1200px",
    "spacing": "comfortable"
  },
  "style": {
    "radius": "sm",
    "shadow": "strong"
  },
  "responsive": {
    "tablet_columns": 2,
    "mobile_columns": 1,
    "mobile_nav": "collapse"
  },
  "sections": [
    {
      "id": "navbar",
      "type": "navbar",
      "brand": "Acme",
      "links": [
        {
          "label": "Features",
          "target": "features"
        },
        {
          "label": "Pricing",
          "target": "pricing"
        }
      ],
      "cta": "Get started",
      "cta_target": "cta"
    },
    {
      "id": "cta",
      "type": "cta",
      "title": "Ready when you are",
      "subtitle": "Set up in five minutes.",
      "cta": "Start free"
    },
    {
      "id": "faq",
      "type": "faq",
      "title": "Questions",
      "items": [
        {
          "question": "Can I cancel any time?",
          "answer": "Yes, from your account page."
        }
      ]
    },
    {
      "id": "pricing",
      "type": "pricing",
      "title": "Simple pricing",
      "tiers": [
        {
          "name": "Starter",
          "price": "$0",
          "period": "/month",
          "features": [
            "1 project"
          ],
          "cta": "Start free",
          "highlighted": false
        },
        {
          "name": "Pro",
