.mf-card:nth-child(3n) .mf-card__thumb{background:linear-gradient(135deg,var(--mf-accent),var(--mf-primary))}
.mf-card h3{font-size:1.15rem;letter-spacing:-.01em}
.mf-card p{color:var(--mf-muted);font-size:.975rem}
