export default function Navbar({ content }) {
  return (
    <header className="mf-nav" id={content.id}>
      <div className="mf-container mf-nav__inner">
        <a className="mf-nav__brand" href="#">{content.brand}</a>
        <input className="mf-nav__toggle" type="checkbox" id="mf-nav-toggle" aria-label="Toggle navigation menu" />
        <label className="mf-nav__burger" htmlFor="mf-nav-toggle" aria-hidden="true">
          <span />
        </label>
        <nav className="mf-nav__links" aria-label="Main">
          {content.links.map((item, i) => (
            <a key={i} href={"#" + (item.target || "")}>{item.label}</a>
          ))}
          {content.cta && (
            <a className="mf-btn mf-btn--primary" href={"#" + (content.cta_target || "")}>{content.cta}</a>
          )}
        </nav>
      </div>
    </header>
  );
}

import Icon from "./Icon.jsx";

export default function Features({ content }) {
  return (
    <section className="mf-section mf-features" id={content.id}>
      <div className="mf-container">
        <div className="mf-head">
          <h2>{content.title}</h2>
          {content.subtitle && (
            <p>{content.subtitle}</p>
          )}
        </div>
        <div className={`mf-grid mf-cols-${content.columns}`}>
          {content.items.map((item, i) => (
            <article key={i} className="mf-feature">
              <span className="mf-icon">
                <Icon name={item.icon} />
              </span>
              <h3>{item.title}</h3>
              <p>{item.body}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

export default function Cards({ content }) {
  return (
    <section className="mf-section mf-cards" id={content.id}>
      <div className="mf-container">
        <div className="mf-head">
          <h2>{content.title}</h2>
          {content.subtitle && (
            <p>{content.subtitle}</p>
          )}
        </div>
        <div className={`mf-grid mf-cols-${content.columns}`}>
          {content.items.map((item, i) => (
            <article key={i} className={`mf-card${item.stat ? " mf-card--stat" : ""}`}>
              <div className="mf-card__thumb" aria-hidden="true" />
