              {item.highlighted && (
                <span className="mf-badge mf-tier__flag">Most popular</span>
              )}
              <h3>{item.name}</h3>
              <p className="mf-tier__price">
                <span className="mf-tier__amount">{item.price}</span>
                {item.period && (
                  <span className="mf-tier__period">{item.period}</span>
                )}
              </p>
              {item.description && (
                <p className="mf-tier__desc">{item.description}</p>
              )}
              <ul className="mf-tier__features">
                {item.features.map((sub, j) => (
                  <li key={j}>
                    <Icon name="check" />
                    <span>{sub}</span>
                  </li>
                ))}
              </ul>
              {item.cta && (
                <a className="mf-btn" href="#">{item.cta}</a>
              )}
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

export default function Faq({ content }) {
  return (
    <section className="mf-section mf-faq-section" id={content.id}>
      <div className="mf-container">
