      </div>
    </section>
  );
}

export default function Footer({ content }) {
  return (
    <footer className="mf-footer" id={content.id}>
      <div className="mf-container">
        <div className="mf-footer__top">
          <div className="mf-footer__about">
            <strong className="mf-footer__brand">{content.brand}</strong>
            {content.tagline && (
              <p className="mf-footer__tagline">{content.tagline}</p>
            )}
          </div>
          <div className="mf-footer__cols">
